// @opencut-test-wasm: real
import { expect, test } from 'bun:test';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { registerAccount, sessionCookie, withAccount } from '@/accounts/server';
import { createCanonicalTestRuntime } from '@/core/__tests__/canonical-runtime-fixture';
import { brandKitTransaction } from './server';
import { newBrandKit, type BrandKitLibrary } from './types';

test('canonical Brand Kits persist, retry after reopen, reject stale writes, and isolate authenticated accounts', async () => {
 const root = await mkdtemp(join(tmpdir(),'opencut-brand-kits-'));
 const previous = process.env.OPENCUT_ACCOUNTS_DIR;
 process.env.OPENCUT_ACCOUNTS_DIR = root;
 try {
  const alice = await registerAccount({ login:'brand-alice',displayName:'Alice',password:[REDACTED] });
  const bob = await registerAccount({ login:'brand-bob',displayName:'Bob',password:[REDACTED] });
  const handler = withAccount(async (request:Request) => { try { const body = request.method === 'POST' ? await request.json():undefined; return Response.json(await brandKitTransaction({ factory:createCanonicalTestRuntime,...(body?{edit:body}:{}) })); } catch (error) {return Response.json({error:String(error)},{status:409});} });
  const request = (token:[REDACTED],edit?:unknown) => handler(new Request('http://localhost:3211/api/brand-kits',{ method:edit?'POST':'GET',headers:{origin:'http://localhost:3211',cookie:sessionCookie(token),'Content-Type':'application/json'},...(edit?{body:JSON.stringify(edit)}:{}) }));
  const original = await (await request(alice.token)).json() as BrandKitLibrary;
  expect(original.kits).toEqual([]);
  const kit={...newBrandKit(),name:'Alice Brand'};
  const edit={expectedRevision:original.revision,requestId:'first-write',change:{type:'upsert',kit}};
  const savedResponse=await request(alice.token,edit); expect(savedResponse.status).

